#include <stdio.h>
int main(void) {
    double rain[2][3] = {{10.0,20.0,30.0},{20.0,30.0,40.0}};
    double all_years = 0.0;
    for (int year = 0; year < 2; year++) {
        double annual = 0.0;
        for (int month = 0; month < 3; month++) annual += rain[year][month];
        printf("year%d=%.1f\n", year + 1, annual);
        all_years += annual;
    }
    printf("annual-mean=%.1f\n", all_years / 2);
    for (int month = 0; month < 3; month++) {
        double column = 0.0;
        for (int year = 0; year < 2; year++) column += rain[year][month];
        printf("month%d-mean=%.1f\n", month + 1, column / 2);
    }
    return 0;
}

