#include <stdio.h>
int sum_items(int data[], int count);
int main(void) {
    int values[3] = {6,-2,9};
    printf("caller-bytes=%u\n", sizeof values);
    int total = sum_items(values, 3);
    printf("total=%d\n", total);
    return 0;
}
int sum_items(int data[], int count) {
    printf("parameter-bytes=%u\n", sizeof data);
    int sum = 0;
    for (int i = 0; i < count; i++) sum += data[i];
    return sum;
}

#include <stdio.h>
int span_sum(const int *begin, const int *end);
int main(void) {
    int values[3] = {5,-2,8};
    int total = span_sum(values, values + 3);
    int empty = span_sum(values, values);
    printf("sum=%d empty=%d\n", total, empty);
    return 0;
}
int span_sum(const int *begin, const int *end) {
    int total = 0;
    while (begin != end) {
        total += *begin;
        begin++;
    }
    return total;
}

#include <stdio.h>
int main(void) {
    int pair[2] = {4,9};
    int other[2] = {20,30};
    int *post = pair;
    int *pre = pair;
    int *value = other;
    int a = *post++;
    int b = *++pre;
    int c = (*value)++;
    printf("read=%d %d %d\n", a, b, c);
    printf("now=%d %d %d\n", *post, *pre, *value);
    return 0;
}

#include <stdio.h>
int main(void) {
    int values[4] = {4,7,10,13};
    int *cursor = values;
    int *last = cursor + 3;
    printf("first=%d third=%d\n", *cursor, *(cursor + 2));
    cursor++;
    printf("forward=%d\n", *cursor);
    cursor--;
    int distance = last - cursor;
    printf("back=%d distance=%d before=%d ordered=%d\n", *cursor, distance, *(last - 1), cursor < last);
    return 0;
}

#include <stdio.h>
void show(const double *data, int count);
void scale(double *data, int count, double factor);
int main(void) {
    double levels[3] = {1.0,2.0,3.0};
    show(levels, 3);
    scale(levels, 3, 2.5);
    show(levels, 3);
    return 0;
}
void show(const double *data, int count) {
    for (int i = 0; i < count; i++) {
        if (i != 0) putchar(' ');
        printf("%.1f", data[i]);
    }
    putchar('\n');
}
void scale(double *data, int count, double factor) {
    for (int i = 0; i < count; i++) data[i] *= factor;
}

