#include <stdio.h>
#define COLS 3
void row_totals(int data[][COLS], int rows);
void column_totals(int data[][COLS], int rows);
int all_total(int data[][COLS], int rows);
int main(void) {
    int data[2][COLS] = {{1,3,5},{2,4,6}};
    row_totals(data, 2);
    column_totals(data, 2);
    printf("all=%d\n", all_total(data, 2));
    return 0;
}
void row_totals(int data[][COLS], int rows) {
    for (int r = 0; r < rows; r++) {
        int sum = 0;
        for (int c = 0; c < COLS; c++) sum += data[r][c];
        printf("row%d=%d\n", r, sum);
    }
}
void column_totals(int data[][COLS], int rows) {
    for (int c = 0; c < COLS; c++) {
        int sum = 0;
        for (int r = 0; r < rows; r++) sum += data[r][c];
        printf("col%d=%d\n", c, sum);
    }
}
int all_total(int data[][COLS], int rows) {
    int sum = 0;
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < COLS; c++) sum += data[r][c];
    return sum;
}

#include <stdio.h>
int total(int rows, int cols, int data[rows][cols]);
int main(void) {
    int first[2][3] = {{1,2,3},{4,5,6}};
    int second[3][2] = {{2,4},{6,8},{10,12}};
    int rows = 2, cols = 4;
    int varying[rows][cols];
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) varying[r][c] = r + c;
    printf("2x3=%d\n", total(2, 3, first));
    printf("3x2=%d\n", total(3, 2, second));
    printf("2x4-VLA=%d\n", total(rows, cols, varying));
    return 0;
}
int total(int rows, int cols, int data[rows][cols]) {
    int sum = 0;
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++) sum += data[r][c];
    return sum;
}

#include <stdio.h>
int sum_one(const int data[], int count);
int sum_two(int data[][3], int rows);
int main(void) {
    int first = sum_one((int[]){4,8,12}, 3);
    int second = sum_two((int[2][3]){{1,2,3},{4,5,6}}, 2);
    printf("one=%d two=%d\n", first, second);
    return 0;
}
int sum_one(const int data[], int count) {
    int sum = 0;
    for (int i = 0; i < count; i++) sum += data[i];
    return sum;
}
int sum_two(int data[][3], int rows) {
    int sum = 0;
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < 3; c++) sum += data[r][c];
    return sum;
}

